#include "rawr_ide_gates.hpp"
#include <fstream>
#include <sstream>
#include <algorithm>
#include <set>
#include <chrono>
#include <system_error>
namespace rawr {
const char* status_name(Status s) { switch(s){ case Status::not_run:return "NOT_RUN"; case Status::pass:return "PASS"; case Status::fail:return "FAIL"; case Status::blocked:return "BLOCKED"; } return "NOT_RUN"; }
std::optional<Status> parse_status(const std::string& s) { if(s=="NOT_RUN")return Status::not_run; if(s=="PASS")return Status::pass; if(s=="FAIL")return Status::fail; if(s=="BLOCKED")return Status::blocked; return std::nullopt; }
std::vector<Gate> default_gates() {
 const char* names[]={"Win32 control hierarchy", "Visible editor readiness", "Editor buffer roundtrip", "Selection and syntax parity", "Multi-document persistence", "File explorer operations", "Search replace correctness", "Terminal cancellation and child cleanup", "PowerShell panel lifecycle", "Debugger breakpoints and watch", "Git operation transactional safety", "VSIX manifest parser", "Extension host API compatibility", "Extension sandbox permissions", "Chat/GhostText model isolation", "Ollama agent tool roundtrip", "Deep2 FFN Q2_K production parity", "Phi3 GPU memory safety", "Agent edit build test rollback", "Snapshot integrity under interruption", "Native compiler target matrix", "ELF and Mach-O object validation", "Apple signing bridge authorization", "Signing job cancellation and receipts", "IDE extension command bridge", "Visual and accessibility regression", "Crash recovery session restore", "Model and GPU resource quotas", "Native Qt-free clean release build", "IDE full system acceptance"};
 std::vector<Gate> g; for(int i=0;i<30;++i)g.push_back({121+i,names[i],Status::not_run,""}); return g;
}
static std::string trim(std::string s){ auto b=s.find_first_not_of(" \t\r\n"); if(b==std::string::npos)return {}; auto e=s.find_last_not_of(" \t\r\n");return s.substr(b,e-b+1); }
static std::string escape_json(const std::string& s){ std::string r; for(unsigned char c:s){ if(c=='"')r+="\\\""; else if(c=='\\')r+="\\\\"; else if(c=='\n')r+="\\n"; else if(c=='\r')r+="\\r"; else if(c=='\t')r+="\\t"; else if(c<32){const char*h="0123456789abcdef";r+="\\u00";r+=h[c>>4];r+=h[c&15];} else r+=char(c);}return r; }
bool safe_evidence_path(const std::filesystem::path& root,const std::filesystem::path& file){ if(file.empty()||file.is_absolute())return false; for(auto& part:file)if(part=="..")return false; auto base=std::filesystem::weakly_canonical(root); auto joined=std::filesystem::weakly_canonical(base/file);auto b=base.begin(),p=joined.begin();for(;b!=base.end();++b,++p){if(p==joined.end()||*p!=*b)return false;}return true; }
bool apply_results(const std::filesystem::path& in,std::vector<Gate>& gates,std::string& error){std::ifstream f(in);if(!f){error="cannot open input";return false;}std::set<int> seen;std::string line;size_t row=0;auto candidate=gates;while(std::getline(f,line)){++row;line=trim(line);if(line.empty()||line[0]=='#')continue;auto a=line.find('|'),b=a==std::string::npos?std::string::npos:line.find('|',a+1);if(a==std::string::npos||b==std::string::npos){error="expected id|STATUS|evidence on line "+std::to_string(row);return false;}int id=0;try{size_t n=0;id=std::stoi(trim(line.substr(0,a)),&n);if(n!=trim(line.substr(0,a)).size())throw 1;}catch(...){error="invalid id on line "+std::to_string(row);return false;}auto s=parse_status(trim(line.substr(a+1,b-a-1)));if(!s||!seen.insert(id).second){error="invalid status or duplicate id on line "+std::to_string(row);return false;}auto it=std::find_if(candidate.begin(),candidate.end(),[&](const Gate&g){return g.id==id;});if(it==candidate.end()){error="unknown gate id "+std::to_string(id);return false;}std::string evidence=trim(line.substr(b+1));if(*s==Status::pass&&evidence.empty()){error="PASS requires evidence for gate "+std::to_string(id);return false;}if(evidence.find('\0')!=std::string::npos){error="invalid evidence";return false;}it->status=*s;it->evidence=evidence;}gates=std::move(candidate);return true;}
bool write_receipt_atomic(const std::filesystem::path& out,const std::vector<Gate>& gates,std::string& error){std::error_code ec;auto parent=out.parent_path();if(!parent.empty())std::filesystem::create_directories(parent,ec);if(ec){error=ec.message();return false;}auto tmp=out;tmp+=".tmp";{std::ofstream f(tmp,std::ios::binary|std::ios::trunc);if(!f){error="cannot create temp receipt";return false;}int passed=0;for(auto&g:gates)passed+=(g.status==Status::pass);f<<"{\n  \"schema\": \"rawrxd-ide-gates-v1\",\n  \"total\": "<<gates.size()<<",\n  \"passed\": "<<passed<<",\n  \"gates\": [\n";for(size_t i=0;i<gates.size();++i){auto&g=gates[i];f<<"    {\"id\": "<<g.id<<", \"name\": \""<<escape_json(g.name)<<"\", \"status\": \""<<status_name(g.status)<<"\", \"evidence\": \""<<escape_json(g.evidence)<<"\"}"<<(i+1<gates.size()?",":"")<<"\n";}f<<"  ]\n}\n";f.flush();if(!f){error="receipt write failed";return false;}}std::filesystem::rename(tmp,out,ec);if(ec){std::filesystem::remove(tmp);error="atomic rename failed: "+ec.message();return false;}return true;}
}
